package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class CourseEnrollmentApiTest {
 StudyApiTest f;CourseEnrollmentStore store;CourseEnrollmentController api;
 @BeforeEach void setup(){f=new StudyApiTest();f.setup();store=mock(CourseEnrollmentStore.class);api=new CourseEnrollmentController(store,f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String body){var r=f.req(method,body);r.removeHeader("If-Match");r.addHeader("If-Match","\"ce0\"");return r;}
 CourseEnrollmentStore.Enrollment value(){return new CourseEnrollmentStore.Enrollment(f.id,f.id,f.group,f.space,f.actor,1,"ENROLLED",3,"PARTICIPANT_AND_OWNER",Instant.now().toString(),Instant.now().toString());}
 @Test void memberChangesOnlyOwnEnrollmentWithIndependentTag()throws Exception{f.role("MEMBER");when(store.change(eq(f.group),eq(f.space),eq(f.id),eq(f.actor),eq(0L),eq("ENROLLED"),anyString())).thenReturn(value());var v=api.change(f.group.toString(),f.id.toString(),req("PUT","{\"state\":\"ENROLLED\"}"));assertEquals(200,v.getStatusCode().value());assertEquals("\"ce1\"",v.getHeaders().getETag());assertEquals("no-store",v.getHeaders().getCacheControl());}
 @Test void viewerMayReadAndOptOutButCannotEnrollOrSeeRoster()throws Exception{f.role("VIEWER");when(store.mine(f.group,f.space,f.id,f.actor,false)).thenReturn(new CourseEnrollmentStore.Mine(value(),"ACTIVE",false));assertEquals(200,api.mine(f.group.toString(),f.id.toString(),req("GET",null)).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.change(f.group.toString(),f.id.toString(),req("PUT","{\"state\":\"ENROLLED\"}"))).getStatusCode().value());when(store.change(eq(f.group),eq(f.space),eq(f.id),eq(f.actor),eq(0L),eq("WITHDRAWN"),anyString())).thenReturn(value());assertEquals(200,api.change(f.group.toString(),f.id.toString(),req("PUT","{\"state\":\"WITHDRAWN\"}")).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),f.id.toString(),req("GET",null)));}
 @Test void ownerRosterGetNeedsNoOriginButMemberCannotReadRoster()throws Exception{var r=req("GET",null);r.removeHeader("Origin");when(store.list(f.group,f.space,f.id,null,20)).thenReturn(new CourseEnrollmentStore.Page(List.of(),null));assertEquals(200,api.list(f.group.toString(),f.id.toString(),r).getStatusCode().value());f.role("MEMBER");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),f.id.toString(),r)).getStatusCode().value());verify(store,times(1)).list(f.group,f.space,f.id,null,20);}
 @Test void exactStateBodyAndStrongZeroCapableEtagsAreRequired(){for(String text:List.of("{}","{\"state\":\"NOT_ENROLLED\"}","{\"state\":\"ENROLLED\",\"participantId\":\"spoof\"}","{\"state\":\"ENROLLED\",\"state\":\"WITHDRAWN\"}","{\"state\":\"ENROLLED\"} {}"))assertThrows(ResponseStatusException.class,()->api.change(f.group.toString(),f.id.toString(),req("PUT",text)));var missing=req("PUT","{\"state\":\"ENROLLED\"}");missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.change(f.group.toString(),f.id.toString(),missing)).getStatusCode().value());for(String tag:List.of("*","W/\"ce1\"","\"co1\"","\"ce01\"","\"ce9999999999999999999\"")){var v=req("PUT","{\"state\":\"ENROLLED\"}");v.removeHeader("If-Match");v.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.change(f.group.toString(),f.id.toString(),v));}verifyNoInteractions(store);}
 @Test void insecureOriginRevokedGrantAndOversizedHistoryAreRejected(){var a=req("PUT","{\"state\":\"ENROLLED\"}");a.setSecure(false);var b=req("PUT","{\"state\":\"ENROLLED\"}");b.addHeader("Origin","https://elsewhere.example");for(var v:List.of(a,b))assertThrows(ResponseStatusException.class,()->api.change(f.group.toString(),f.id.toString(),v));verifyNoInteractions(f.auth,store);var history=req("GET",null);history.addParameter("limit","11");assertThrows(ResponseStatusException.class,()->api.mineHistory(f.group.toString(),f.id.toString(),history));var body=req("GET","{}");assertThrows(ResponseStatusException.class,()->api.mine(f.group.toString(),f.id.toString(),body));when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of()));assertThrows(ResponseStatusException.class,()->api.mine(f.group.toString(),f.id.toString(),req("GET",null)));verifyNoInteractions(store);}
}
